function nero_knowledge(): array {$entries=[
 'identity'=>['mots'=>['petica','identite','هوية','بطاقة','carte'],'fr'=>'PETICA relie votre compagnon à une identité permanente, une carte et deux destinations QR. Les données publiées peuvent changer sans remplacer les QR.','ar'=>'تربط PETICA رفيقك بهوية دائمة وبطاقة ووجهتي QR. يمكنك تحديث البيانات المنشورة دون تغيير الرموز.','route'=>'comment-ca-marche.html'],
