function nero_ask(array $b,?array $u): array {$message=mb_strtolower(text_field($b,'message',2000,true));$m=strtr($message,['é'=>'e','è'=>'e','ê'=>'e','à'=>'a','ô'=>'o','أ'=>'ا','إ'=>'ا','آ'=>'ا']);$m=preg_replace('/[\x{064B}-\x{065F}\x{0640}]/u','',$m);if(preg_match('/prix|tarif|combo|promo|livraison|remise|سعر|تخفيض|توصيل|اسعار/u',$m)){if(str_contains($m,'tracker'))$key='world';else{$products=q('SELECT name_fr,name_ar,price_tnd FROM products WHERE active=1 AND commercial_approved=1 ORDER BY id')->fetchAll();$lines=array_map(fn($p)=>$p['name_'.lang()].' : '.money((int)round((float)$p['price_tnd']*1000)),$products);return ['answer'=>implode(' · ',$lines).tr('. Livraison : 8 TND. Le configurateur vérifie les remises et les codes. Un Combo non approuvé reste indisponible.','. التوصيل: 8 TND. حاسبة السعر تتحقق من التخفيضات والرموز. الباقة غير المعتمدة تبقى غير متاحة.'),'source'=>'catalogue','action'=>'tarifs.html'];}}
 if(!isset($key)){$score=0;$key=null;foreach(nero_knowledge() as $k=>$entry){$n=0;foreach($entry['mots'] as $word)if(str_contains($m,$word))$n+=mb_strlen($word);if($n>$score){$score=$n;$key=$k;}}}if(!$key)return ['answer'=>tr('Je n’ai pas de réponse vérifiée à cette question. Précisez votre demande ou contactez PETICA.','لا أملك إجابة موثوقة لهذا السؤال. وضّح طلبك أو تواصل مع PETICA.'),'source'=>'limite','action'=>'contact.html'];$r=nero_knowledge()[$key];return ['answer'=>$r[lang()],'source'=>'PETICA · '.$key,'action'=>$r['route']];}
